import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"创建型模式 (Creational Patterns)","description":"","frontmatter":{},"headers":[],"relativePath":"creational/overview.md","filePath":"creational/overview.md","lastUpdated":1790910996000}`),a={name:`creational/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="创建型模式-creational-patterns" tabindex="-1">创建型模式 (Creational Patterns) <a class="header-anchor" href="#创建型模式-creational-patterns" aria-label="Permalink to “创建型模式 (Creational Patterns)”">​</a></h1><p><strong>主要解决的问题</strong>：对象的创建方式。这类模式通过将对象创建的过程与其具体类型分离，提高系统的灵活性和可扩展性。 创建型模式把&quot;对象如何被创建&quot;这一变化点封装起来，客户端只依赖抽象接口，而不必关心具体类型与构造细节。常见的实现手段包括隐藏构造函数、把创建逻辑集中到工厂或建造者、通过复制已有实例来生成新对象等。</p><h3 id="本目录包含的模式" tabindex="-1">本目录包含的模式 <a class="header-anchor" href="#本目录包含的模式" aria-label="Permalink to “本目录包含的模式”">​</a></h3><ul><li><a href="/hello-design-patterns/creational/singleton">单例模式</a>：保证一个类只有一个实例，并提供全局访问点。</li><li><a href="/hello-design-patterns/creational/factory-method">工厂方法模式</a>：定义创建对象的接口，让子类决定实例化哪个类。</li><li><a href="/hello-design-patterns/creational/abstract-factory">抽象工厂模式</a>：创建一系列相关或相互依赖的对象，而无需指定具体类。</li><li><a href="/hello-design-patterns/creational/builder">建造者模式</a>：把复杂对象的构建过程与其表示分离，同样的构建过程可以创建不同的表示。</li><li><a href="/hello-design-patterns/creational/prototype">原型模式</a>：通过复制已有实例来创建新对象，避免重复执行昂贵的初始化。</li><li><a href="/hello-design-patterns/creational/multiton">多例模式</a>：保证每个键最多只有一个实例，是有键的单例变体。</li><li><a href="/hello-design-patterns/creational/object-pool">对象池模式</a>：管理可复用对象的池子，减少昂贵对象的频繁创建与销毁。</li><li><a href="/hello-design-patterns/creational/service-locator">服务定位器模式</a>：通过集中注册表按名称或类型获取服务实例，实现服务使用的解耦。</li></ul><h3 id="选用建议" tabindex="-1">选用建议 <a class="header-anchor" href="#选用建议" aria-label="Permalink to “选用建议”">​</a></h3><ul><li>只需要一个全局实例时优先考虑单例，并注意多线程下的初始化安全。</li><li>创建逻辑需要随环境变化或需要解耦具体类型时，选择工厂方法或抽象工厂。</li><li>构造参数多、步骤有先后依赖时，使用建造者代替一长串构造函数。</li><li>对象创建成本高且可复用时，使用原型或对象池。</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};